const sections = [
  ['1、Pi Agent | 从最小工具开始', '把工具保持简单，意味着你可以自行决定工作方式。先建立一个能重复使用的最小流程，再按需求补充功能。', '如果你喜欢自己挑选组件、编写扩展，这种方式很容易形成个人习惯。需要投入的时间，也应当计入选择的成本。'],
  ['2、Claude Code | 开箱即用的协作', '完整的工作流可以减少配置时间，让注意力回到正在解决的问题。理解代码、调整实现与验证结果，最好处在同一段连续的上下文里。', '对于日常开发，工具之间的衔接和稳定性往往比功能数量更影响体验。先用一个真实任务试一试，再判断是否适合自己。'],
  ['3、DeepSeek Harness | 按需搭建流程', '把任务拆成清楚的步骤，有助于观察输入和输出。每一步都应该有可检查的结果，而不是只看最后的完成提示。', '定制流程会带来灵活性，也会增加维护成本。选择之前，可以先写下那些必须满足的约束。'],
  ['4、把选择放回实际工作', '从最近的一次工作开始：你花了多长时间理解问题，又有多少时间在重复操作？这些事实，比抽象地比较能力更有帮助。', '保留能减轻日常负担的部分，让流程随着经验逐步变化。适合别人的工具，不一定适合你的项目。'],
  ['5、从小任务开始验证', '挑一个范围清楚、能够独立验收的任务，记录完成过程。看看工具是否能够解释改动，能否帮助你发现遗漏。', '在熟悉之前，不必一次调整整个工作方式。小步尝试更容易看见收益，也更容易回到原来的流程。'],
  ['6、给自己的阅读留一张地图', '长文里的章节是理解结构的线索。有目录之后，可以先看整体安排，再选择最需要的部分深入阅读。', '阅读不一定按顺序进行。跳回前一章核对概念，或直接查看最后的建议，都是很自然的阅读方式。'],
  ['7、总结：找到自己的节奏', '工具最终服务于你的判断。把需要做的事情说清楚，把完成的标准定下来，再让工具帮助你更顺畅地到达那里。', '记住真正带来改变的那些细节，下一次选择时，它们就是最可靠的参考。']
];

export function fixtureHTML({ dark = false, semantic = false } = {}) {
  const content = sections.map(([heading, first, second], index) => semantic
    ? `<h${index === 1 ? 3 : 2}>${heading}</h${index === 1 ? 3 : 2}><p>${first}</p><p>${second}</p>`
    : `<span style="font-weight:700">${heading}</span><br><br><span>${first}</span><br><br><span>${second}</span><br><br><span>这里是一段用于验证长文滚动的示例正文，包含<strong>正文中的局部加粗</strong>，它不应该变成目录项。章节之间保留足够的阅读空间，便于检查跳转位置和当前章节高亮。</span><br><br>`).join('');
  return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>x-reader · 本地阅读演示</title><style>
  :root{--bg:${dark ? '#000' : '#fff'};--text:${dark ? '#e7e9ea' : '#202624'};--muted:${dark ? '#8b9890' : '#839087'};--line:${dark ? '#26372e' : '#e9eeeb'};--soft:${dark ? '#142019' : '#f5f7f5'}}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.85 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}.shell{display:grid;grid-template-columns:200px 640px 400px;max-width:1240px;margin:0 auto}.rail{position:sticky;top:0;height:100vh;padding:30px 30px 30px 8px}.wordmark{font-size:23px;letter-spacing:-1px;font-weight:700;margin-bottom:43px}.rail p{font-size:17px;margin:23px 0;color:var(--muted)}.rail .selected{color:var(--text);font-weight:600}.rail small{position:absolute;bottom:35px;font-size:10px;letter-spacing:1.5px;color:var(--muted)}main{min-width:0;border-left:1px solid var(--line);border-right:1px solid var(--line)}.page-header{position:sticky;top:0;height:64px;display:flex;align-items:center;gap:25px;padding:0 27px;background:var(--bg);z-index:2;border-bottom:1px solid var(--line);font-size:18px;font-weight:600}.page-header span{font-size:10px;font-weight:400;letter-spacing:1px;color:var(--muted);margin-left:auto}.post{padding:28px 30px 80px}.author{display:flex;gap:11px;align-items:center;margin-bottom:23px}.avatar{display:grid;place-items:center;background:#173e2c;color:#c2e6ce;border-radius:50%;width:42px;height:42px;font-size:14px;font-weight:600}.author strong{font-size:14px;line-height:1.4}.author small{display:block;font-size:12px;line-height:1.6;color:var(--muted)}.author a{margin-left:auto;color:var(--muted);font-size:11px;text-decoration:none}.post-title{font-size:28px;line-height:1.45;letter-spacing:-.8px;margin:0 0 16px;font-weight:650}.intro{color:var(--muted);font-size:14px;line-height:1.9;margin:0 0 35px}.article-body{font-size:17px;line-height:1.95;overflow-wrap:anywhere}.article-body strong,.article-body span[style]{color:var(--text)}.article-body h2{font-size:20px;margin-top:45px}.article-body h3{font-size:18px;margin-top:40px}.right-rail{position:sticky;top:0;height:100vh;padding:25px 24px;color:var(--muted);font-size:13px}.rail-card{border:1px solid var(--line);border-radius:16px;padding:16px;margin-bottom:16px}.rail-card h2{margin:0 0 14px;color:var(--text);font-size:18px}.rail-card.related{height:200px}.rail-card.trends{height:420px}.end{border-top:1px solid var(--line);margin-top:25px;padding-top:20px;font-size:12px;color:var(--muted)}
  @media(max-width:1100px){.shell{grid-template-columns:100px minmax(0,640px) 1fr}.rail{padding-left:16px}.rail p{font-size:13px}.wordmark{font-size:17px}.right-rail{display:none}}@media(max-width:700px){.shell{display:block}.rail,.right-rail{display:none}.post{padding:24px 22px 60px}.post-title{font-size:25px}.page-header{padding:0 22px}.article-body{font-size:16px}}
  </style></head><body><div class="shell"><aside class="rail"><div class="wordmark">read / slowly</div><p>首页</p><p>探索</p><p class="selected">长文阅读</p><p>书签</p><p>个人资料</p><small>LOCAL DEMO</small></aside><main><div data-testid="primaryColumn"><header class="page-header">←<div>长文</div><span>本地演示</span></header><article class="post" data-testid="tweet"><div class="author"><div class="avatar">xr</div><div><strong>x-reader demo</strong><small>@reader_demo</small></div><a role="link" href="/demo/status/100"><time>示例文章</time></a></div><h1 class="post-title" ${semantic ? 'data-testid="twitterArticleTitle"' : ''}>三种工具，三种工作方式</h1><p class="intro">这是一篇用于验证目录交互的示例长文。先看整体结构，再找到你想读的那一节。</p><div class="article-body" data-testid="${semantic ? 'twitterArticleRichTextView' : 'tweetText'}"><span>选择工具之前，先想清楚自己的需求。这篇文章从上手方式、流程与日常使用出发，整理几个值得留意的角度。</span><br><br>${content}</div><div class="end">阅读结束 · 愿每一次长文阅读，都有清晰的方向。</div></article></div></main><aside class="right-rail" data-testid="sidebarColumn"><section class="rail-card related"><h2>相关用户</h2><div data-testid="UserCell">示例作者</div><p>本地演示推荐信息</p></section><section class="rail-card trends"><h2>有什么新鲜事</h2><div data-testid="trend">演示趋势</div></section></aside></div></body></html>`;
}
